const treatTagPalette={none:{background:'#d9ded9',foreground:'#303831'},white:{background:'#fff',foreground:'#263126'},green:{background:'#35a853',foreground:'#fff'},yellow:{background:'#ffdc3d',foreground:'#332c15'},red:{background:'#e84b40',foreground:'#fff'}};
function updateTreatTagFields(){const select=document.querySelector('#treatTagColor');const details=document.querySelector('#treatTagDetails');const chosen=select.value;details.hidden=!chosen;const colors=treatTagPalette[chosen.toLowerCase()]||treatTagPalette.none;select.style.backgroundColor=colors.background;select.style.color=colors.foreground;if(!chosen){document.querySelector('#treatTagNumber').value='';document.querySelector('#treatDateValue').textContent='';document.querySelector('#treatDateValue').dataset.value='';}}
function updateFormChoices(){const diagnoses=Object.keys(state.config.issues);chipPicker(document.querySelector('#diagnosisChips'),{'':diagnoses},diagnosisSelection,false);document.querySelectorAll('#diagnosisChips .select-chip').forEach(chip=>chip.addEventListener('click',()=>{diagnosisSelection.splice(0,diagnosisSelection.length,chip.textContent);issueSelection.length=0;renderSymptoms();}));renderSymptoms();chipPicker(document.querySelector('#appearanceChips'),{'':state.config.appearance},appearanceSelection);const sel=document.querySelector('#treatTagColor');const noTag=new Option('No Tag','',true,true);noTag.style.backgroundColor=treatTagPalette.none.background;noTag.style.color=treatTagPalette.none.foreground;sel.replaceChildren(noTag);for(const color of state.config.treatColors){const option=new Option(color,color);const style=treatTagPalette[color.toLowerCase()]||{background:color,foreground:'#20251f'};option.style.backgroundColor=style.background;option.style.color=style.foreground;sel.add(option);}updateTreatTagFields();}
document.querySelector('#treatTagColor').addEventListener('change',updateTreatTagFields);
document.querySelector('#changeDiagnosis').onclick=()=>{diagnosisSelection.length=0;issueSelection.length=0;renderSymptoms();};
document.querySelector('#changeColor').onclick=()=>{document.querySelector('#colorChips').hidden=false;document.querySelector('#colorHeading').textContent='Animal color';document.querySelector('#changeColor').hidden=true;};
document.querySelector('#newAnimalButton').onclick=()=>{document.querySelector('#animalForm').reset();diagnosisSelection.length=issueSelection.length=appearanceSelection.length=colorSelection.length=0;document.querySelector('#penInput').value='';document.querySelector('#penInput').dataset.section='';document.querySelector('#penHeading').textContent='Pen';document.querySelector('#changePen').hidden=true;document.querySelector('#treatDateValue').textContent='';document.querySelector('#treatDateValue').dataset.value='';updateFormChoices();openPenPicker(()=>document.querySelector('#formDialog').showModal());};
const penInput=document.querySelector('#penInput');
const openPenPicker=onChoose=>showChoice('Choose a Pen',state.config.sections,(pen,section)=>{penInput.value=pen;penInput.dataset.section=section;document.querySelector('#penHeading').textContent=`Pen: ${pen}`;document.querySelector('#changePen').hidden=false;updateRequiredFields();onChoose?.();},true);
document.querySelector('#changePen').onclick=()=>openPenPicker();
document.querySelector('#treatDateButton').onclick=showTreatDatePicker;
function editAnimalRecord(record){
  editingRecordId=record.id;document.querySelector('#animalForm').reset();
  diagnosisSelection.length=issueSelection.length=appearanceSelection.length=colorSelection.length=0;
  const diagnosis=record.diagnosis||Object.entries(state.config.issues).find(([,values])=>(record.issues||[]).some(issue=>values.includes(issue)))?.[0]||Object.keys(state.config.issues)[0]||'';
  if(diagnosis)diagnosisSelection.push(diagnosis);issueSelection.push(...(record.issues||[]));appearanceSelection.push(...(record.appearance||[]));if(record.color)colorSelection.push(record.color);
  document.querySelector('#penInput').value=record.pen||'';document.querySelector('#penInput').dataset.section=record.section||'';document.querySelector('#penHeading').textContent=`Pen: ${record.pen||''}`;document.querySelector('#changePen').hidden=false;
  document.querySelector('#animalTag').value=record.animalTag||'';document.querySelector('#intakeNotes').value=record.notes||'';document.querySelector('#treatTagNumber').value=record.treatTagNumber||'';
  document.querySelector('#treatDateValue').textContent=record.treatDate?`Last treated ${record.treatDate}`:'';document.querySelector('#treatDateValue').dataset.value=record.treatDate||'';
  updateFormChoices();document.querySelector('#treatTagColor').value=record.treatTagColor||'';updateTreatTagFields();
  document.querySelector('#animalFormTitle').textContent='Edit animal';document.querySelector('#saveAnimalButton').textContent='Save changes';updateRequiredFields();document.querySelector('#formDialog').showModal();
}
document.querySelector('#formDialog').addEventListener('close',()=>{editingRecordId=null;document.querySelector('#animalFormTitle').textContent='Enter sick animal';document.querySelector('#saveAnimalButton').textContent='Save animal';});
document.querySelector('#animalForm').addEventListener('submit',e=>{
  if(e.submitter?.value==='cancel')return;e.preventDefault();
  const pen=document.querySelector('#penInput').value;if(!pen){toast('Choose a pen first');return;}
  if(!diagnosisSelection[0]){toast('Choose a diagnosis');return;}
  const color=colorSelection[0];if(!color){toast('Choose the animal color');return;}
  const fields={pen,section:document.querySelector('#penInput').dataset.section||'',animalTag:document.querySelector('#animalTag').value.trim(),diagnosis:diagnosisSelection[0],issues:[...issueSelection],appearance:[...appearanceSelection],color,treatTagColor:document.querySelector('#treatTagColor').value,treatTagNumber:document.querySelector('#treatTagNumber').value.trim(),treatDate:document.querySelector('#treatDateValue').dataset.value||'',notes:document.querySelector('#intakeNotes').value.trim()};
  const existing=editingRecordId&&state.records.find(record=>record.id===editingRecordId);
  if(existing)Object.assign(existing,fields);else state.records.push({id:crypto.randomUUID(),date:dateKey(),createdAt:Date.now(),...fields,status:'open'});
  document.querySelector('#formDialog').close();persist();toast(existing?'Animal changes saved':'Animal added to today');
});
document.body.addEventListener('click',e=>{
  const card=e.target.closest('.animal-card');
  if(card&&!e.target.closest('button,a,input,textarea,select')){toggleCardDetails(card);return;}
  const menuButton=e.target.closest('[data-record-menu]');
  if(menuButton){const record=state.records.find(r=>r.id===menuButton.dataset.recordMenu);if(record)openRecordMenu(record);return;}
  const b=e.target.closest('[data-action]');if(!b)return;const record=state.records.find(r=>r.id===b.dataset.id);if(!record)return;
  switch(b.dataset.action){case'watch':{const checkedDate=record.date||dateKey(),followUpDate=addDays(checkedDate,1),checkedCopy={...structuredClone(record),id:crypto.randomUUID(),date:checkedDate,createdAt:Date.now(),status:'moved',checkedDate,followUpDate,followUpRecordId:record.id};delete checkedCopy.followUpFromId;record.date=followUpDate;record.status='open';record.followUpFromId=checkedCopy.id;delete record.checkedDate;delete record.followUpDate;delete record.followUpRecordId;state.records.push(checkedCopy);persist();toast('Checked today · entry moved to tomorrow');break;}case'undo-watch':undoWatch(record);break;case'fine':record.statusBeforeFine=record.status;record.status='fine';record.resolvedDate=dateKey();persist();toast('Marked as fine');break;case'undo-fine':undoFine(record);break;case'pull':record.status='pulled';persist();toast('Marked pulled');break;case'treat':openAction(record,'treat');break;case'undo':undoPull(record);break;}
});
function toggleCardDetails(card){const details=card.querySelector('.card-expanded-details');if(!details)return;const expanded=card.classList.toggle('expanded');details.hidden=!expanded;card.setAttribute('aria-expanded',String(expanded));const hint=card.querySelector('.card-expand-hint');if(hint){hint.firstElementChild.textContent=expanded?'Hide details':'More details';hint.lastElementChild.textContent=expanded?'⌃':'⌄';}}
document.body.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.animal-card')){e.preventDefault();toggleCardDetails(e.target);}});
function addDays(key,n){const d=new Date(`${key}T12:00:00`);d.setDate(d.getDate()+n);return dateKey(d);}
function openAction(record,kind){
  currentActionId=record.id;const content=document.querySelector('#actionContent');content.innerHTML='';const title=document.querySelector('#actionTitle');
  document.querySelector('#actionEyebrow').textContent=`${esc(formatAnimal(record))}`;
  {
    const editing=kind==='treatEdit',savedTreatment=editing?record.treatment:null;
    title.textContent=editing?'Edit treatment':'Record treatment';
    const baseWrap=document.createElement('div');
    const home=`Home · Pen ${record.pen}`;
    const destinations=[home,...(state.config.destinations||['8 · Hospital','WSP · Hospital','SP · Sickpen','44SP · Buller / fat ration'])];
    const savedDestination=savedTreatment?.destination||record.destination||home;
    if(savedDestination&&!destinations.includes(savedDestination))destinations.push(savedDestination);
    baseWrap.innerHTML='<div class="field-label">Send to</div><div id="destinationChips" class="chip-area"></div><div class="field-label">Choose one base product</div><div id="baseChips" class="chip-area"></div><section id="secondaryProductSection" hidden><div class="field-label">Additional products</div><div id="secondaryChips" class="chip-area"></div></section><label class="field-label" for="treatmentTemperature">Temperature (°F)</label><input id="treatmentTemperature" type="text" inputmode="decimal" autocomplete="off"><label class="field-label" for="treatmentNotes">Notes</label><textarea id="treatmentNotes" rows="3"></textarea>';
    content.append(baseWrap);
    chipPicker(document.querySelector('#destinationChips'),{'':destinations},[savedDestination],false);
    const baseSelection=savedTreatment?.base?[savedTreatment.base]:[],baseProducts=[...state.config.baseProducts];
    if(savedTreatment?.base&&!baseProducts.includes(savedTreatment.base))baseProducts.push(savedTreatment.base);
    chipPicker(document.querySelector('#baseChips'),{'':baseProducts},baseSelection,false);
    const renderSecondary=(base,selected)=>{const allowed=state.config.compatible[base]||[],required=(state.config.requiredSecondary||{})[base]||[];const values=[...new Set([...allowed,...required])];const initial=selected||(state.config.defaultSecondary||{})[base]||[];chipPicker(document.querySelector('#secondaryChips'),{'':values},[...initial,...required]);document.querySelectorAll('#secondaryChips .select-chip').forEach(chip=>{if(required.includes(chip.textContent)){chip.classList.add('active','locked');chip.disabled=true;}});document.querySelector('#secondaryProductSection').hidden=false;};
    document.querySelector('#baseChips').addEventListener('click',()=>{const base=document.querySelector('#baseChips .select-chip.active')?.textContent||'';if(base)renderSecondary(base);});
    if(savedTreatment?.base)renderSecondary(savedTreatment.base,savedTreatment.secondary||[]);
    const temperatureInput=document.querySelector('#treatmentTemperature');temperatureInput.value=savedTreatment?.temperature||'';temperatureInput.addEventListener('blur',()=>{temperatureInput.value=formatTemperature(temperatureInput.value);});
    document.querySelector('#treatmentNotes').value=savedTreatment?.notes||'';
    document.querySelector('#actionSaveButton').textContent=editing?'Save treatment changes':'Save treatment';
  }
  document.querySelector('#actionForm').dataset.kind=kind;document.querySelector('#actionDialog').showModal();
}
document.querySelector('#actionForm').addEventListener('submit',e=>{
  if(e.submitter?.value==='cancel')return;e.preventDefault();const record=state.records.find(r=>r.id===currentActionId);if(!record)return;
  const kind=e.currentTarget.dataset.kind;
  {
    const destination=document.querySelector('#destinationChips .select-chip.active')?.textContent||'';
    record.destination=destination;
    const base=document.querySelector('#baseChips .select-chip.active')?.textContent;if(!base){toast('Choose a base product');return;}
    const secondary=[...document.querySelectorAll('#secondaryChips .select-chip.active')].map(chip=>chip.textContent);
    const temperature=formatTemperature(document.querySelector('#treatmentTemperature').value);
    record.status='treated';
    record.treatment={base,secondary,temperature,notes:document.querySelector('#treatmentNotes').value.trim(),destination};
    record.treatedDate=dateKey();
  }
  document.querySelector('#actionDialog').close();persist();toast(kind==='treatEdit'?'Treatment updated':'Treatment saved');
});
function configListRow(value,kind,key,group='',index=0){return `<div class="config-row-wrap" data-config-row data-kind="${kind}" data-key="${esc(key)}" data-group="${esc(group)}" data-index="${index}" data-can-drag="true"><div class="config-swipe-action config-delete-action"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M9 7V4h6v3m3 0-.8 13H6.8L6 7m4 4v5m4-5v5"/></svg><span>Delete</span></div><div class="config-swipe-action config-edit-action"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m4 16.5-.8 4.3 4.3-.8L19.8 7.7a2.3 2.3 0 0 0-3.2-3.2L4 16.5ZM14.8 6.5l3.2 3.2"/></svg><span>Edit</span></div><div class="config-list-row"><span class="config-row-label">${esc(value)}</span><button type="button" class="config-drag-handle" aria-label="Drag to reorder ${esc(value)}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="8" cy="6" r="1.4"/><circle cx="16" cy="6" r="1.4"/><circle cx="8" cy="12" r="1.4"/><circle cx="16" cy="12" r="1.4"/><circle cx="8" cy="18" r="1.4"/><circle cx="16" cy="18" r="1.4"/></svg></button></div></div>`;}
function configAddRow(kind,group='',placeholder='Add an option'){return `<div class="config-add-row"><input type="text" data-config-input="${kind}" data-group="${esc(group)}" placeholder="${placeholder}" aria-label="${placeholder}"><button type="button" class="secondary-button" data-config-action="add-item" data-kind="${kind}" data-group="${esc(group)}">Add</button></div>`;}
function configArrayPanel(key,title,description){const values=configDraft[key]||[];return `<section class="config-panel"><div class="config-panel-heading"><div><h3>${title}</h3><p>${description}</p></div><span class="config-count">${values.length}</span></div><div class="config-row-list">${values.map((x,i)=>configListRow(x,'array-item',key,'',i)).join('')||'<span class="config-empty">No options yet</span>'}</div>${configAddRow('array',key,`Add ${title.toLowerCase().replace(/s$/,'')}`)}</section>`;}
function configGroupPanel(key,title,description,itemLabel){const groups=configDraft[key]||{};return `<section class="config-panel"><div class="config-panel-heading"><div><h3>${title}</h3><p>${description}</p></div><span class="config-count">${Object.keys(groups).length}</span></div><div class="config-group-list">${Object.entries(groups).map(([name,values],groupIndex)=>`<div class="config-group-card"><div class="config-group-heading">${configListRow(name,'map-key',key,'',groupIndex)}</div><div class="config-row-list">${values.map((x,i)=>configListRow(x,'map-item',key,name,i)).join('')||'<span class="config-empty">No options yet</span>'}</div>${configAddRow(key,name,`Add ${itemLabel}`)}</div>`).join('')}</div><div class="config-new-group"><button type="button" class="secondary-button" data-config-create-category="${key}">＋ Add diagnosis category</button></div></section>`;}
function configSectionsPanel(){const sections=configDraft.sections||{},entries=Object.entries(sections);return `<section class="config-panel config-sections-manager"><div class="config-panel-heading"><div><h3>Pen sections</h3><p>Add, rename, remove, or reorder the sections used for pen selection. Removing a section hides it from pen selection but keeps its pens saved for when you add it again.</p></div><span class="config-count">${entries.length}</span></div><div class="config-row-list">${entries.map(([name],i)=>configListRow(name,'map-key','sections','',i)).join('')||'<span class="config-empty">No sections yet</span>'}</div><div class="config-new-group"><button type="button" class="secondary-button" data-config-create-category="sections">＋ Add pen section</button></div></section>${entries.map(([name,pens])=>`<section class="config-panel config-section-panel"><div class="config-panel-heading"><div><h3>${esc(name)}</h3><p>Manage pens in the ${esc(name)} section.</p></div><span class="config-count">${pens.length}</span></div><div class="config-row-list">${pens.map((pen,i)=>configListRow(pen,'map-item','sections',name,i)).join('')||'<span class="config-empty">No pens in this section</span>'}</div>${configAddRow('sections',name,`Add pen to ${name}`)}</section>`).join('')}`;}

function configProductRules(){const bases=configDraft.baseProducts||[],secondaries=configDraft.secondaryProducts||[];return `<section class="config-panel"><div class="config-panel-heading"><div><h3>Product rules</h3><p>Tap a product bubble to change its rule for each base product.</p></div></div><div class="config-product-list">${bases.map(base=>{const compatible=configDraft.compatible[base]||[],defaults=(configDraft.defaultSecondary||{})[base]||[],required=(configDraft.requiredSecondary||{})[base]||[];return `<article class="config-product-rule"><h4>${esc(base)}</h4>${[['Allowed with this base','compatible',compatible],['Selected by default','defaultSecondary',defaults],['Always required','requiredSecondary',required]].map(([title,kind,active])=>`<div class="config-rule-row"><span>${title}</span><div class="config-toggle-bubbles">${secondaries.map(item=>`<button type="button" class="config-toggle ${active.includes(item)?'active':''}" data-config-action="toggle-product" data-kind="${kind}" data-base="${esc(base)}" data-product="${esc(item)}" aria-pressed="${active.includes(item)}">${esc(item)}</button>`).join('')||'<span class="config-empty">Add secondary products above</span>'}</div></div>`).join('')}</article>`;}).join('')||'<p class="config-empty">Add a base product to set product rules.</p>'}</div></section>`;}
let configTab='pens';
function renderConfigEditor(){const root=document.querySelector('#configEditor');if(!configDraft)return;const tabs=[['pens','Pens'],['animal','Animal'],['products','Products'],['destinations','Destinations']];root.innerHTML=`<p class="config-editor-intro">Shape the lists and treatment rules for this feedlot. Changes take effect after you save.</p><nav class="config-tabs" role="tablist" aria-label="Configuration sections">${tabs.map(([id,label])=>`<button type="button" class="config-tab ${configTab===id?'active':''}" role="tab" aria-selected="${configTab===id}" data-config-tab="${id}">${label}</button>`).join('')}</nav><section class="config-tab-panel" role="tabpanel" ${configTab!=='pens'?'hidden':''}>${configSectionsPanel()}</section><section class="config-tab-panel" role="tabpanel" ${configTab!=='animal'?'hidden':''}>${configGroupPanel('issues','Diagnoses and symptoms','Create diagnosis categories and the symptom flags shown for each one.','Add a symptom')}${configArrayPanel('appearance','Animal description flags','Choose the quick-select flags shown under “Animal Description”.')}${configArrayPanel('colors','Animal colors','Choose a color for the required animal color step.')}${configArrayPanel('treatColors','Treat tag colors','Choose the colors available for treat tags.')}</section><section class="config-tab-panel" role="tabpanel" ${configTab!=='products'?'hidden':''}>${configArrayPanel('baseProducts','Base products','Only one base product can be selected for a treatment.')}${configArrayPanel('secondaryProducts','Secondary products','These can be enabled per base product below.')}${configProductRules()}</section><section class="config-tab-panel" role="tabpanel" ${configTab!=='destinations'?'hidden':''}>${configArrayPanel('destinations','Pull destinations','Hospital pens and other destination choices.')}</section>`;}
function addUnique(list,value){const clean=value.trim();if(clean&&!list.some(item=>item.toLowerCase()===clean.toLowerCase()))list.push(clean);}
document.querySelector('#editConfigButton').onclick=()=>{configDraft=structuredClone(state.config);configDraft.compatible||={};configDraft.defaultSecondary||={};configDraft.requiredSecondary||={};configDraft.archivedSections||={};configTab='pens';renderConfigEditor();document.querySelector('#configDialog').showModal();};
let configEditTarget=null,configCreateCategoryKey=null,configGesture=null,configLongPressTimer=null,configUndoAction=null;
function clearConfigUndo(){configUndoAction=null;const node=document.querySelector('#toast');if(node?.classList.contains('has-action')){node.classList.remove('show','has-action');clearTimeout(toastTimer);}}
function editConfigRow(row){configCreateCategoryKey=null;const {kind,key,group,index}=row.dataset;configEditTarget={kind,key,group,index:Number(index)};const value=kind==='array-item'?configDraft[key][Number(index)]:kind==='map-item'?configDraft[key][group][Number(index)]:Object.keys(configDraft[key])[Number(index)];document.querySelector('#configItemTitle').textContent=kind==='map-key'?'Edit category':'Edit option';const input=document.querySelector('#configItemValue');input.value=value;document.querySelector('#configItemDialog').showModal();setTimeout(()=>{input.focus();input.select();},80);}
function removeConfigRow(row){const {kind,key,group,index}=row.dataset;const name=row.querySelector('.config-row-label').textContent;confirmAction(kind==='map-key'&&key==='sections'?'Remove pen section':'Delete configuration option',kind==='map-key'&&key==='sections'?`Remove “${name}” from the active pen sections? Its pens will be kept in saved configuration and restored if this section is added again.`:`Delete “${name}”?`,kind==='map-key'&&key==='sections'?'Remove section':'Delete').then(confirmed=>{if(!confirmed)return;const snapshot=structuredClone(configDraft);if(kind==='array-item'){const removed=configDraft[key].splice(Number(index),1)[0];if(key==='baseProducts')for(const map of ['compatible','defaultSecondary','requiredSecondary'])delete configDraft[map][removed];if(key==='secondaryProducts')for(const map of ['compatible','defaultSecondary','requiredSecondary'])for(const base of Object.keys(configDraft[map]))configDraft[map][base]=configDraft[map][base].filter(x=>x!==removed);}else if(kind==='map-item')configDraft[key][group].splice(Number(index),1);else{const category=Object.keys(configDraft[key])[Number(index)];if(key==='sections'){configDraft.archivedSections||={};const pens=configDraft.sections[category]||[];if(pens.length)configDraft.archivedSections[category]=[...pens];}delete configDraft[key][category];}configUndoAction=()=>{configDraft=snapshot;configUndoAction=null;renderConfigEditor();};renderConfigEditor();toastAction(kind==='map-key'&&key==='sections'?'Pen section removed':'Configuration option deleted','Undo',()=>configUndoAction?.());});}
function moveConfigRow(row,target){const {kind,key,group,index}=row.dataset,from=Number(index);if(target===from)return;clearConfigUndo();const identity=item=>`${item.dataset.kind}|${item.dataset.key}|${item.dataset.group}|${item.querySelector('.config-row-label')?.textContent}`,before=new Map([...configEditor.querySelectorAll('[data-config-row]')].map(item=>[identity(item),item.getBoundingClientRect().top]));if(kind==='array-item'){const list=configDraft[key],item=list.splice(from,1)[0];list.splice(target,0,item);}else if(kind==='map-item'){const list=configDraft[key][group],item=list.splice(from,1)[0];list.splice(target,0,item);}else{const entries=Object.entries(configDraft[key]),entry=entries.splice(from,1)[0];entries.splice(target,0,entry);configDraft[key]=Object.fromEntries(entries);}renderConfigEditor();for(const item of configEditor.querySelectorAll('[data-config-row]')){const oldTop=before.get(identity(item));if(oldTop==null)continue;const delta=oldTop-item.getBoundingClientRect().top;if(Math.abs(delta)<1)continue;item.style.transition='none';item.style.transform=`translateY(${delta}px)`;requestAnimationFrame(()=>{item.style.transition='transform .16s cubic-bezier(.2,.75,.25,1)';item.style.transform='';setTimeout(()=>{item.style.transition='';},180);});}}
function configRowsFor(row){return [...document.querySelectorAll(`[data-config-row][data-kind="${CSS.escape(row.dataset.kind)}"][data-key="${CSS.escape(row.dataset.key)}"][data-group="${CSS.escape(row.dataset.group||'')}"]`)];}
const configEditor=document.querySelector('#configEditor');
configEditor.addEventListener('click',e=>{const createCategory=e.target.closest('[data-config-create-category]');if(createCategory){configEditTarget=null;configCreateCategoryKey=createCategory.dataset.configCreateCategory;document.querySelector('#configItemTitle').textContent=configCreateCategoryKey==='sections'?'Add pen section':'Add diagnosis category';const input=document.querySelector('#configItemValue');input.value='';document.querySelector('#configItemDialog').showModal();setTimeout(()=>input.focus(),80);return;}const tab=e.target.closest('[data-config-tab]');if(tab){configTab=tab.dataset.configTab;renderConfigEditor();return;}const action=e.target.closest('.config-swipe-action');if(action){const row=action.closest('[data-config-row]');if(action.classList.contains('config-delete-action'))removeConfigRow(row);else editConfigRow(row);return;}const button=e.target.closest('[data-config-action]');if(!button)return;const {configAction:actionName,kind,group}=button.dataset;const input=configEditor.querySelector(`[data-config-input="${kind}"][data-group="${CSS.escape(group||'')}"]`);if(actionName==='add-item'){const value=input?.value.trim();if(!value)return;clearConfigUndo();if(kind.startsWith('new-')){const target=kind.slice(4);if(value in configDraft[target]){toast('That category already exists');return;}configDraft[target][value]=[];}else if(kind==='array'){addUnique(configDraft[group]||(configDraft[group]=[]),value);if(group==='baseProducts'){configDraft.compatible[value]||=[];configDraft.defaultSecondary[value]||=[];configDraft.requiredSecondary[value]||=[];}if(group==='secondaryProducts')for(const base of configDraft.baseProducts)configDraft.compatible[base]||=[];}else addUnique(configDraft[kind][group]||(configDraft[kind][group]=[]),value);renderConfigEditor();return;}if(actionName==='toggle-product'){const base=button.dataset.base,product=button.dataset.product;clearConfigUndo();const list=configDraft[kind][base]||(configDraft[kind][base]=[]);const index=list.indexOf(product);if(index>=0)list.splice(index,1);else{if(kind!=='compatible')addUnique(configDraft.compatible[base]||(configDraft.compatible[base]=[]),product);addUnique(list,product);if(kind==='compatible'){for(const rule of ['defaultSecondary','requiredSecondary'])configDraft[rule][base]=(configDraft[rule][base]||[]).filter(x=>x!==product);}else{const other=kind==='defaultSecondary'?'requiredSecondary':'defaultSecondary';configDraft[other][base]=(configDraft[other][base]||[]).filter(x=>x!==product);}}renderConfigEditor();}});
configEditor.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-config-input]')){e.preventDefault();const group=e.target.dataset.group;configEditor.querySelector(`[data-config-action="add-item"][data-kind="${CSS.escape(e.target.dataset.configInput)}"][data-group="${CSS.escape(group||'')}"]`)?.click();}});
function animateGhostPlacement(g,before){const parent=g.placeholder.parentElement,items=[...configRowsFor(g.row).filter(item=>item!==g.wrap),g.placeholder],positions=new Map(items.map(item=>[item,item.getBoundingClientRect().top]));if(before)parent.insertBefore(g.placeholder,before);else parent.append(g.placeholder);requestAnimationFrame(()=>{for(const item of items){if(!item.isConnected)continue;const delta=positions.get(item)-item.getBoundingClientRect().top;if(Math.abs(delta)<1)continue;item.style.transition='none';item.style.transform=`translateY(${delta}px)`;requestAnimationFrame(()=>{item.style.transition='transform .14s cubic-bezier(.2,.75,.25,1)';item.style.transform='';setTimeout(()=>{item.style.transition='';},160);});}});}
function updateConfigGhost(g){const peers=configRowsFor(g.row).filter(item=>item!==g.wrap),before=peers.find(item=>g.lastY<item.getBoundingClientRect().top+item.getBoundingClientRect().height/2);const currentBefore=g.placeholder.nextElementSibling;if((before||null)!==currentBefore)animateGhostPlacement(g,before);}
function autoScrollConfigDrag(g){if(configGesture!==g||g.mode!=='drag')return;const rect=configEditor.getBoundingClientRect(),edge=48,y=g.lastY;let speed=0;if(y<rect.top+edge)speed=-Math.ceil(1+(rect.top+edge-y)/6);else if(y>rect.bottom-edge)speed=Math.ceil(1+(y-(rect.bottom-edge))/6);if(speed){const old=configEditor.scrollTop;configEditor.scrollTop+=Math.max(-14,Math.min(14,speed));if(configEditor.scrollTop!==old)updateConfigGhost(g);}g.scrollFrame=requestAnimationFrame(()=>autoScrollConfigDrag(g));}
function startConfigDrag(g){if(g.mode==='drag')return true;if(!g.canDrag||g.row.dataset.canDrag==='false')return false;g.mode='drag';const wrap=g.row,rect=wrap.getBoundingClientRect();g.wrap=wrap;g.startTop=rect.top;g.startLeft=rect.left;g.placeholder=document.createElement('div');g.placeholder.className='config-row-ghost';g.placeholder.style.height=`${rect.height}px`;g.placeholder.setAttribute('aria-hidden','true');wrap.parentElement.insertBefore(g.placeholder,wrap);wrap.style.width=`${rect.width}px`;wrap.style.left=`${rect.left}px`;wrap.style.top=`${rect.top}px`;wrap.style.position='fixed';wrap.style.zIndex='1000';wrap.style.pointerEvents='none';wrap.classList.add('drag-active');g.scrollFrame=requestAnimationFrame(()=>autoScrollConfigDrag(g));return true;}
function beginConfigGesture(row,x,y,id,type,canDrag=false){if(!row||configGesture)return;row.classList.remove('open-delete','open-edit');configGesture={row,startX:x,startY:y,lastX:x,lastY:y,mode:'pending',pointerId:id,pointerType:type,canDrag};}
function moveConfigGesture(x,y,id,event){const g=configGesture;if(!g||g.pointerId!==id)return;const dx=x-g.startX,dy=y-g.startY;g.lastX=x;g.lastY=y;if(g.mode==='pending'&&(Math.abs(dx)>11||Math.abs(dy)>11)){if(Math.abs(dx)>Math.abs(dy)*1.35)g.mode='swipe';else if(!startConfigDrag(g))g.mode='blocked';}if(g.mode==='drag'){event?.preventDefault();g.wrap.style.left=`${g.startLeft+dx}px`;g.wrap.style.top=`${g.startTop+dy}px`;updateConfigGhost(g);}else if(g.mode==='swipe'){event?.preventDefault();const wrap=g.row,slidingRow=wrap.querySelector('.config-list-row'),offset=Math.max(-88,Math.min(88,dx));slidingRow.style.transform=`translateX(${offset}px)`;wrap.classList.toggle('preview-delete',dx<0);wrap.classList.toggle('preview-edit',dx>0);wrap.classList.toggle('swipe-armed',Math.abs(dx)>=64);}}
function finishConfigGesture(id){const g=configGesture;if(!g||g.pointerId!==id)return;const dx=g.lastX-g.startX;configGesture=null;if(g.scrollFrame)cancelAnimationFrame(g.scrollFrame);if(g.mode==='drag'){const target=[...g.placeholder.parentElement.querySelectorAll('[data-config-row]')].filter(item=>item!==g.wrap).filter(item=>item.compareDocumentPosition(g.placeholder)&Node.DOCUMENT_POSITION_FOLLOWING).length;g.placeholder.replaceWith(g.wrap);for(const prop of ['position','left','top','width','zIndex','pointerEvents'])g.wrap.style[prop]='';g.wrap.classList.remove('drag-active');if(target>=0)moveConfigRow(g.row,target);return;}if(g.mode==='swipe'){const wrap=g.row,slidingRow=wrap.querySelector('.config-list-row'),commit=Math.abs(dx)>=68;wrap.classList.remove('preview-delete','preview-edit','swipe-armed');if(commit){slidingRow.style.transition='transform .14s ease-out';slidingRow.style.transform=`translateX(${dx<0?-110:110}px)`;setTimeout(()=>{slidingRow.style.transition='';slidingRow.style.transform='';if(dx<0)removeConfigRow(wrap);else editConfigRow(wrap);},150);}else slidingRow.style.transform='';}}
configEditor.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;const row=e.target.closest('[data-config-row]');if(row&&!e.target.closest('.config-swipe-action')){const canDrag=!!e.target.closest('.config-drag-handle');beginConfigGesture(row,e.clientX,e.clientY,e.pointerId,e.pointerType,canDrag);row.setPointerCapture?.(e.pointerId);}});
configEditor.addEventListener('pointermove',e=>{if(e.pointerType!=='touch')moveConfigGesture(e.clientX,e.clientY,e.pointerId,e);});
configEditor.addEventListener('pointerup',e=>{if(e.pointerType!=='touch')finishConfigGesture(e.pointerId);});configEditor.addEventListener('pointercancel',e=>{if(e.pointerType!=='touch')finishConfigGesture(e.pointerId);});
configEditor.addEventListener('touchstart',e=>{const t=e.changedTouches[0],row=e.target.closest('[data-config-row]');if(row&&!e.target.closest('.config-swipe-action'))beginConfigGesture(row,t.clientX,t.clientY,'touch','touch',!!e.target.closest('.config-drag-handle'));},{passive:true});
configEditor.addEventListener('touchmove',e=>{if(!configGesture||configGesture.pointerId!=='touch')return;const t=e.changedTouches[0];moveConfigGesture(t.clientX,t.clientY,'touch',e);},{passive:false});
configEditor.addEventListener('touchend',()=>finishConfigGesture('touch'),{passive:true});configEditor.addEventListener('touchcancel',()=>finishConfigGesture('touch'),{passive:true});
configEditor.addEventListener('contextmenu',e=>{if(e.target.closest('[data-config-row]'))e.preventDefault();});
document.querySelector('#configItemForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel'){configCreateCategoryKey=null;configEditTarget=null;return;}e.preventDefault();const value=document.querySelector('#configItemValue').value.trim();if(!value)return;if(configCreateCategoryKey){const key=configCreateCategoryKey,existing=Object.keys(configDraft[key]).some(name=>name.toLowerCase()===value.toLowerCase());if(existing){toast('That category already exists');return;}clearConfigUndo();const archivedName=key==='sections'?Object.keys(configDraft.archivedSections||{}).find(name=>name.toLowerCase()===value.toLowerCase()):null;configDraft[key][value]=archivedName?[...configDraft.archivedSections[archivedName]]:[];if(archivedName)delete configDraft.archivedSections[archivedName];configCreateCategoryKey=null;document.querySelector('#configItemDialog').close();renderConfigEditor();return;}if(!configEditTarget)return;clearConfigUndo();const {kind,key,group,index}=configEditTarget;if(kind==='array-item'){const list=configDraft[key],old=list[index];if(list.some((item,i)=>i!==index&&item.toLowerCase()===value.toLowerCase())){toast('That option already exists');return;}list[index]=value;if(key==='baseProducts'){for(const map of ['compatible','defaultSecondary','requiredSecondary']){configDraft[map][value]=configDraft[map][old]||[];if(old!==value)delete configDraft[map][old];}}if(key==='secondaryProducts'&&old!==value)for(const map of ['compatible','defaultSecondary','requiredSecondary'])for(const base of Object.keys(configDraft[map]))configDraft[map][base]=configDraft[map][base].map(item=>item===old?value:item);}else if(kind==='map-item'){if(configDraft[key][group].some((item,i)=>i!==index&&item.toLowerCase()===value.toLowerCase())){toast('That option already exists');return;}configDraft[key][group][index]=value;}else{const old=Object.keys(configDraft[key])[index];if(old!==value&&value in configDraft[key]){toast('That category already exists');return;}const entries=Object.entries(configDraft[key]);entries[index][0]=value;configDraft[key]=Object.fromEntries(entries);}document.querySelector('#configItemDialog').close();configEditTarget=null;configCreateCategoryKey=null;renderConfigEditor();});
function renderConfigPreview(){const title={pens:'Pen selection',animal:'Animal entry',products:'Treatment products',destinations:'Pull destinations'}[configTab]||'How this will look';document.querySelector('#configPreviewTitle').textContent=title;const root=document.querySelector('#configPreviewContent'),bubbleList=values=>`<div class="preview-bubbles">${values.map(value=>`<span class="preview-bubble">${esc(value)}</span>`).join('')||'<span class="config-empty">No options configured</span>'}</div>`;if(configTab==='pens')root.innerHTML=Object.entries(configDraft.sections).map(([section,pens])=>`<div class="preview-section"><h3>${esc(section)}</h3><div class="pen-grid config-preview-pen-grid">${pens.map(pen=>`<span class="pen-option">${esc(pen)}</span>`).join('')}</div></div>`).join('')||'<p class="config-empty">No pens configured</p>';else if(configTab==='animal')root.innerHTML=`<h3>Diagnosis</h3>${Object.entries(configDraft.issues).map(([category,flags])=>`<div class="preview-section"><strong>${esc(category)}</strong>${bubbleList(flags)}</div>`).join('')}<h3>Animal description</h3>${bubbleList(configDraft.appearance)}<h3>Animal color</h3>${bubbleList(configDraft.colors.map(color=>`● ${color}`))}<h3>Treat tag color</h3>${bubbleList(configDraft.treatColors)}`;else if(configTab==='products')root.innerHTML=`<h3>Base product</h3>${bubbleList(configDraft.baseProducts)}${configDraft.baseProducts.map(base=>`<div class="preview-section"><strong>${esc(base)} · additional products</strong>${bubbleList([...(configDraft.defaultSecondary[base]||[]).map(x=>`${x} · default`),...(configDraft.requiredSecondary[base]||[]).map(x=>`${x} · required`),...(configDraft.compatible[base]||[]).filter(x=>!(configDraft.defaultSecondary[base]||[]).includes(x)&&!(configDraft.requiredSecondary[base]||[]).includes(x))])}</div>`).join('')}`;else root.innerHTML=`<h3>Send to</h3>${bubbleList(configDraft.destinations)}`;document.querySelector('#configPreviewDialog').showModal();}
document.querySelector('#previewConfigButton').onclick=renderConfigPreview;
document.querySelector('#configForm').addEventListener('submit',e=>{if(e.submitter?.value==='cancel'){configDraft=null;clearConfigUndo();return;}e.preventDefault();clearConfigUndo();state.config=configDraft;document.querySelector('#configDialog').close();configDraft=null;persist();toast('Configuration saved');});
function downloadJson(payload,filename){const contents=JSON.stringify(payload,null,2);if(window.CowboyNative?.exportJson){window.CowboyNative.exportJson(filename,contents);return;}const blob=new Blob([contents],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validateSchema(payload,expectedFormat){if(!payload||typeof payload!=='object'||Array.isArray(payload))throw new Error('The selected file is not a Cowboy data file.');const version=payload.schemaVersion??0;if(!Number.isInteger(version)||version<0)throw new Error('The file has an invalid schema version.');if(version>DATA_SCHEMA_VERSION)throw new Error(`This file uses Cowboy data format version ${version}, newer than this app supports (${DATA_SCHEMA_VERSION}). Update Cowboy before importing it.`);if(payload.format&&payload.format!==expectedFormat)throw new Error(`This is a ${payload.format} file, not a ${expectedFormat} file.`);return version;}
document.querySelector('#exportButton').onclick=()=>downloadJson({format:BACKUP_FORMAT,schemaVersion:DATA_SCHEMA_VERSION,exportedAt:new Date().toISOString(),configVersion:state.configVersion||2,config:state.config,records:state.records},`cowboy-backup-v${DATA_SCHEMA_VERSION}-${dateKey()}.json`);
