document.querySelector('#exportConfigButton').onclick=()=>downloadJson({format:CONFIG_FORMAT,schemaVersion:CONFIG_SCHEMA_VERSION,exportedAt:new Date().toISOString(),configVersion:state.configVersion||2,config:state.config},`cowboy-config-v${CONFIG_SCHEMA_VERSION}-${dateKey()}.json`);
document.querySelector('#importConfigButton').onclick=()=>document.querySelector('#importConfigFile').click();
document.querySelector('#importConfigFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());if(!imported||typeof imported!=='object'||Array.isArray(imported)||imported.format!==CONFIG_FORMAT)throw new Error('This file is not a Cowboy configuration export.');const version=imported.schemaVersion??0;if(!Number.isInteger(version)||version<0)throw new Error('The configuration file has an invalid version.');if(version>CONFIG_SCHEMA_VERSION)throw new Error(`This configuration uses format version ${version}, newer than this app supports (${CONFIG_SCHEMA_VERSION}). Update Cowboy before importing it.`);const source=imported.config;if(!source||typeof source!=='object'||Array.isArray(source))throw new Error('The file does not contain a valid configuration.');for(const key of ['sections','issues'])if(source[key]!==undefined&&(!source[key]||typeof source[key]!=='object'||Array.isArray(source[key])||Object.values(source[key]).some(values=>!Array.isArray(values)||values.some(value=>typeof value!=='string'))))throw new Error(`The ${key} configuration is invalid.`);for(const key of ['appearance','colors','treatColors','baseProducts','secondaryProducts','destinations'])if(source[key]!==undefined&&(!Array.isArray(source[key])||source[key].some(value=>typeof value!=='string')))throw new Error(`The ${key} configuration is invalid.`);for(const key of ['compatible','defaultSecondary','requiredSecondary'])if(source[key]!==undefined&&(!source[key]||typeof source[key]!=='object'||Array.isArray(source[key])||Object.values(source[key]).some(values=>!Array.isArray(values)||values.some(value=>typeof value!=='string'))))throw new Error(`The ${key} product rules are invalid.`);if(!await confirmAction('Import feedlot setup?',`This will replace the current pens, diagnoses, flags, colors, destinations, and treatment product rules. Animal records will stay on this device.\n\nFile: ${file.name}\nExport the current setup first if you may need to restore it.

File contains ${Object.keys(source.sections||{}).length} pen sections and ${Object.keys(source.issues||{}).length} diagnoses.`,'Import setup',false))return;const migrated=migrateConfig({...structuredClone(DEFAULT_CONFIG),...source},imported.configVersion||0);state={...state,...migrated,records:state.records};persist();toast('Configuration imported');}catch(error){showMessage('Could not import configuration',error.message||'Choose a valid Cowboy configuration JSON file.');}finally{e.target.value='';}});
document.querySelector('#importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());validateSchema(imported,BACKUP_FORMAT);if(!Array.isArray(imported.records)||!imported.config||typeof imported.config!=='object'||Array.isArray(imported.config))throw new Error('This file does not look like a Cowboy backup.');if(!await confirmAction('Replace all Cowboy data?',`File: ${file.name}\nThis full backup contains ${imported.records.length} animal records and feedlot setup. Importing it will replace all current records and settings on this device.\n\nExport a full backup first if you may need to restore what is here now.`,'Replace all data'))return;const migrated=migrateConfig({...structuredClone(DEFAULT_CONFIG),...imported.config},imported.configVersion||0);state={...migrated,records:imported.records};persist();toast('Backup restored');}catch(error){showMessage('Could not import backup',error.message||'Choose a valid Cowboy JSON backup.');}finally{e.target.value='';}});
document.querySelector('#exportAnimalsButton').onclick=()=>downloadJson({format:ANIMAL_DATA_FORMAT,schemaVersion:DATA_SCHEMA_VERSION,exportedAt:new Date().toISOString(),records:state.records},`cowboy-animals-v${DATA_SCHEMA_VERSION}-${dateKey()}.json`);
document.querySelector('#importAnimalsButton').onclick=()=>document.querySelector('#importAnimalsFile').click();
document.querySelector('#importAnimalsFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const imported=JSON.parse(await file.text());if(Array.isArray(imported)){if(imported.some(record=>!record||typeof record!=='object'||Array.isArray(record)))throw new Error('The animal data file contains an invalid record.');}else{validateSchema(imported,ANIMAL_DATA_FORMAT);if(!Array.isArray(imported.records)||imported.records.some(record=>!record||typeof record!=='object'||Array.isArray(record)))throw new Error('This file does not contain valid animal data.');}const records=Array.isArray(imported)?imported:imported.records;if(!await confirmAction('Import animal records?',`File: ${file.name}\nThis will add ${records.length} records to the records already on this device. Matching record IDs will be skipped. Current records and feedlot setup will be kept.

Review the imported records in History after the import.`,'Import records',false))return;const existingIds=new Set(state.records.map(record=>record.id).filter(Boolean)),newRecords=records.filter(record=>!record.id||!existingIds.has(record.id)).map(record=>({...record,id:record.id||crypto.randomUUID()})),skipped=records.length-newRecords.length;state.records.push(...newRecords);persist();toast(`Imported ${newRecords.length} animals${skipped?`; skipped ${skipped} duplicates`:''}`);}catch(error){showMessage('Could not import animal data',error.message||'Choose a valid Cowboy animal data JSON file.');}finally{e.target.value='';}});
function showMessage(title,message){document.querySelector('#messageTitle').textContent=title;document.querySelector('#messageContent').textContent=message;document.querySelector('#messageDialog').showModal();}
function confirmAction(title,message,actionLabel='Confirm',danger=true){return new Promise(resolve=>{const dialog=document.querySelector('#confirmDialog'),action=document.querySelector('#confirmActionButton');document.querySelector('#confirmTitle').textContent=title;document.querySelector('#confirmMessage').textContent=message;action.textContent=actionLabel;action.classList.toggle('danger-button',danger);action.classList.toggle('primary-button',!danger);dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}
let androidUpdateReady=false;
function updateButtonState(label,disabled=false){const button=document.querySelector('#checkAndroidUpdate');button.textContent=label;button.disabled=disabled;}
function setUpdateReady(version,showPrompt){androidUpdateReady=true;updateButtonState('Install update');document.querySelector('#updateStatus').textContent=`Cowboy ${version} is downloaded and ready to install.`;document.querySelector('#updateProgressPanel').hidden=true;if(showPrompt){document.querySelector('#updateDownloadedMessage').textContent=`Cowboy ${version} has been downloaded. Install it now or later.`;document.querySelector('#updateDownloadedDialog').showModal();}}
window.CowboyUpdate={
  onCowboyUpdateState(state,message){const status=document.querySelector('#updateStatus');status.textContent=message;if(state==='checking'){updateButtonState('Checking…',true);document.querySelector('#updateProgressPanel').hidden=true;}else if(state==='downloading'){updateButtonState('Downloading…',true);document.querySelector('#updateProgressPanel').hidden=false;document.querySelector('#updateProgressLabel').textContent=message;document.querySelector('#updateProgressPercent').textContent='';const bar=document.querySelector('#updateProgressBar');bar.classList.add('indeterminate');bar.removeAttribute('aria-valuenow');document.querySelector('#updateProgressFill').style.width='36%';}},
  onCowboyUpdateAvailable(version){updateButtonState('Check for update');document.querySelector('#updateStatus').textContent=`Cowboy ${version} is available.`;document.querySelector('#updateAvailableTitle').textContent=`Cowboy ${version} is available`;document.querySelector('#updateAvailableDialog').showModal();},
  onCowboyUpdateCurrent(version){updateButtonState('Check for update');document.querySelector('#updateProgressPanel').hidden=true;document.querySelector('#updateStatus').textContent=`You’re using the latest version (Cowboy ${version}).`;},
  onCowboyUpdateProgress(version,percent,received,total){const panel=document.querySelector('#updateProgressPanel'),bar=document.querySelector('#updateProgressBar');panel.hidden=false;document.querySelector('#updateProgressLabel').textContent=`Downloading Cowboy ${version}…`;const fill=document.querySelector('#updateProgressFill'),percentNode=document.querySelector('#updateProgressPercent');if(percent>=0){bar.classList.remove('indeterminate');bar.setAttribute('aria-valuenow',String(percent));bar.setAttribute('aria-valuetext',`${percent}% downloaded`);fill.style.width=`${percent}%`;percentNode.textContent=`${percent}%`;}else{bar.classList.add('indeterminate');bar.removeAttribute('aria-valuenow');bar.setAttribute('aria-valuetext','Downloading');fill.style.width='36%';percentNode.textContent=total>0?`${Math.round(received/1024/1024)} MB`:'';}},
  onCowboyUpdateDownloaded(version){setUpdateReady(version,true);},
  onCowboyUpdateError(message){androidUpdateReady=false;updateButtonState('Check for update');document.querySelector('#updateProgressPanel').hidden=true;document.querySelector('#updateStatus').textContent=`Update unavailable: ${message}`;}
};
document.querySelector('#downloadUpdateButton').onclick=()=>{document.querySelector('#updateAvailableDialog').close();document.querySelector('#updateProgressPanel').hidden=false;document.querySelector('#updateProgressLabel').textContent='Starting download…';if(window.CowboyNative)window.CowboyNative.downloadUpdate();};
document.querySelector('#installUpdateButton').onclick=()=>{document.querySelector('#updateDownloadedDialog').close();if(window.CowboyNative)window.CowboyNative.installUpdate();};
if(window.CowboyNative){document.querySelector('#androidTools').hidden=false;document.querySelector('#androidVersion').textContent=`Installed version ${window.CowboyNative.versionName()}`;document.querySelector('#checkAndroidUpdate').onclick=()=>androidUpdateReady?window.CowboyNative.installUpdate():window.CowboyNative.checkForUpdate();document.querySelector('#shareCrashReport').onclick=()=>window.CowboyNative.shareCrashReport();try{const saved=JSON.parse(window.CowboyNative.updateState());if(saved.ready)setUpdateReady(saved.version,false);}catch{}}
function toast(message){const node=document.querySelector('#toast');node.replaceChildren(document.createTextNode(message));node.classList.remove('has-action');node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),2600);}
function toastAction(message,label,action){const node=document.querySelector('#toast'),text=document.createElement('span'),button=document.createElement('button');text.textContent=message;button.type='button';button.className='toast-action';button.textContent=label;button.onclick=()=>{node.classList.remove('show','has-action');clearTimeout(toastTimer);action();};node.replaceChildren(text,button);node.classList.add('show','has-action');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('show'),6000);}
